import java.util.*;
import java.io.*;

public class Div680 {
    static int n, mod, offset;
    static int[][][] dp;

    static int solve(int done, int i, int diff) {
        if (i == n)
            return diff > 0 ? 1 : 0;
        if (dp[done][i][diff + offset] != -1)
            return dp[done][i][diff + offset];
        int rem = n - i;
        int ans = 0;
        int l = 0;
        while (l < rem) {
            int r = (done == 1) ? 0 : l;
            while (r < rem) {
                ans += solve(done | (l < r ? 1 : 0), i + 1, diff + l - r);
                ans %= mod;
                r++;
            }
            l++;
        }
        dp[done][i][diff + offset] = ans;
        return ans;
    }

    static long solve2(int i) {
        if (i == n - 1)
            return 0;
        long ans = (n - i) * 1L * solve2(i + 1);
        ans %= mod;
        int l = 0;
        while (l < n - i) {
            int r = l + 1;
            while (r < n - i) {
                ans += solve(1, i + 1, l - r);
                ans %= mod;
                r++;
            }
            l++;
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = sc.nextInt();
        mod = sc.nextInt();
        offset = n * (n - 1);
        dp = new int[2][n][2 * offset + 1];
        for (int a = 0; a < 2; a++)
            for (int b = 0; b < n; b++)
                for (int c = 0; c <= 2 * offset; c++)
                    dp[a][b][c] = -1;
        pw.println(solve2(0));
        pw.flush();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;
        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
